### 4.2. C (POSIX sockets)

```c
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    int s = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in srv = {0};
    srv.sin_family = AF_INET;
    srv.sin_port   = htons(80);
    inet_pton(AF_INET, "93.184.216.34", &srv.sin_addr); // example.com

    connect(s, (struct sockaddr *)&srv, sizeof(srv));

    const char *req = "GET / HTTP/1.1\r\nHost: example.com\r\n\r\n";
    send(s, req, strlen(req), 0);

    char buf[4096];
    ssize_t n;
    while ((n = recv(s, buf, sizeof(buf), 0)) > 0) {
        write(STDOUT_FILENO, buf, n);
    }

    /* Graceful shutdown */
    shutdown(s, SHUT_WR);          // Skickar FIN

    /* Läs tills fjärränden stänger */
    while ((n = recv(s, buf, sizeof(buf), 0)) > 0) {
        // eventuellt bearbeta kvarvarande data
    }

    close(s);                      // Släpper resurser
    return 0;
}
```

