### 4.3. Java (java.net.Socket)

```java
import java.io.*;
import java.net.*;

public class TcpCloseDemo {
    public static void main(String[] args) throws IOException {
        try (Socket socket = new Socket("example.com", 80)) {
            OutputStream out = socket.getOutputStream();
            InputStream  in  = socket.getInputStream();

            out.write("GET / HTTP/1.1\r\nHost: example.com\r\n\r\n".getBytes());
            out.flush();

            // Läs svar
            BufferedReader br = new BufferedReader(new InputStreamReader(in));
            String line;
            while ((line = br.readLine()) != null && !line.isEmpty()) {
                System.out.println(line);
            }

            // Graceful shutdown
            socket.shutdownOutput();   // Skickar FIN

            // Läs tills fjärränden också stänger sin skrivände
            while ((line = br.readLine()) != null) {
                System.out.println(line);
            }
            // När read() returnerar null är anslutningen stängd
        }   // socket.close() kallas automatiskt i try‑with‑resources
    }
}
```

